40	/* ===== DOM REFS ===== */
41	var world = document.getElementById('world');
42	var viewport = document.getElementById('viewport');
43	var parallaxBack = document.getElementById('parallax-back');
44	var parallaxMid = document.getElementById('parallax-mid');
45	var particleCanvas = document.getElementById('particle-canvas');
46	var pCtx = particleCanvas.getContext('2d');
47	var progressFill = document.getElementById('progress-fill');
48	var zoneLabels = document.getElementById('zone-labels');
49	var hud = document.getElementById('hud');
50	
51	/* ===== CAMERA STATE ===== */
52	var camera = { x: scenes[0].x, y: scenes[0].y, z: scenes[0].z, r: scenes[0].r || 0 };
53	var currentScene = 0;
54	var isAnimating = false;
55	var overviewActive = false;
56	var prevOverviewScene = 0;
57	var particleActive = false;
58	var pRaf = null;
59	var particles = [];
60	var typewriterDone = false;
61	var sceneAnimations = {};
62	var connCanvas = null;
63	var connCtx = null;
64	var connDrawn = false;
65	var navVersion = 0;
66	var currentNavTimeline = null;
67	var originalFinalQuestionHTML = '';
68	var impactScenes = [6, 9, 10, 11, 12, 28, 31, 33, 34];
69	function isImpactScene(i) { return impactScenes.indexOf(i) >= 0; }
70	
71	/* ===== CAMERA ENGINE ===== */
72	function applyCameraTransform() {
73	  var vw = window.innerWidth;
74	  var vh = window.innerHeight;
75	  world.style.transform = 'translate3d('+(vw/2)+'px,'+(vh/2)+'px,0) scale('+camera.z+') rotate('+(camera.r||0)+'deg) translate3d('+(-camera.x)+'px,'+(-camera.y)+'px,0)';
76	  var pOffX = (camera.x) * 0.08;
77	  var pOffY = (camera.y) * 0.08;
78	  parallaxBack.style.transform = 'translate3d('+(-pOffX)+'px,'+(-pOffY)+'px,0)';
79	  var mOffX = (camera.x) * 0.25;
80	  var mOffY = (camera.y) * 0.25;
81	  parallaxMid.style.transform = 'translate3d('+(-mOffX)+'px,'+(-mOffY)+'px,0)';
82	}
83	
84	/* ===== ECOSYSTEM CAMERA TARGET ===== */
85	function getSceneCameraTarget(index) {
86	  var s = scenes[index];
87	  if (index !== 21) return { x: s.x, y: s.y };
88	  var el = document.getElementById('scene-' + s.id);
89	  if (!el) return { x: s.x, y: s.y };
90	  var elements = [];
91	  var center = el.querySelector('.constellation-center');
92	  if (center) elements.push(center);
93	  var nodes = el.querySelectorAll('.tool-node');
94	  nodes.forEach(function(n) { elements.push(n); });
95	  var minL = Infinity, minT = Infinity, maxR = -Infinity, maxB = -Infinity;
96	  for (var i = 0; i < elements.length; i++) {
97	    var r = elements[i].getBoundingClientRect();
98	    if (r.width === 0 && r.height === 0) continue;
99	    minL = Math.min(minL, r.left); minT = Math.min(minT, r.top);
100	    maxR = Math.max(maxR, r.right); maxB = Math.max(maxB, r.bottom);
101	  }
102	  if (minL === Infinity) return { x: s.x, y: s.y };
103	  var cCX = (minL + maxR) / 2, cCY = (minT + maxB) / 2;
104	  var vw = window.innerWidth, vh = window.innerHeight;
105	  return {
106	    x: (cCX - vw / 2) / camera.z + camera.x,
107	    y: (cCY - vh / 2) / camera.z + camera.y
108	  };
109	}
110	
111	/* ===== SCENE STATE MANAGEMENT ===== */
112	function setActiveScene(index) {
113	  document.querySelectorAll('.scene').forEach(function(el) {
114	    el.classList.remove('is-active', 'is-entering', 'is-leaving');
115	    el.style.opacity = '';
116	  });
117	  var el = document.getElementById('scene-' + scenes[index].id);
118	  if (el) el.classList.add('is-active');
119	}
120	
121	function goToScene(index, playEntrance) {
122	  if (index < 0 || index >= scenes.length) return;
123	  if (overviewActive) { exitOverview(); }
124	  if (currentNavTimeline) { currentNavTimeline.kill(); currentNavTimeline = null; }
125	
126	  var fromIndex = currentScene;
127	  var fromEl = document.getElementById('scene-' + scenes[fromIndex].id);
128	  var targetEl = document.getElementById('scene-' + scenes[index].id);
129	  if (!fromEl || !targetEl) return;
130	  var navId = ++navVersion;
131	
132	  // Clean stale states
133	  document.querySelectorAll('.scene').forEach(function(el) {
134	    el.classList.remove('is-entering', 'is-leaving');
135	  });
136	
137	  triggerSceneLeave(fromIndex);
138	
139	  // Measure content bounds BEFORE prepare (avoids GSAP entrance scale distorting rects)
140	  targetEl.classList.add('is-measuring');
141	  var bounds = getSceneContentBounds(targetEl);
142	  targetEl.classList.remove('is-measuring');
143	
144	  // PREPARE target entrance state while still hidden
145	  prepareSceneForEnter(index);
146	
147	  // Calculate safe zoom and camera target
148	  var s = scenes[index];
149	  var preferredZ = s.z;
150	  var finalZ = calculateSafeFitZoom(bounds.width, bounds.height, preferredZ);
151	  var camTarget = getSceneCameraTarget(index);
152	
153	  var settled = false;
154	  var isEntrancePlayed = false;
155	
156	  function entranceCallback() {
157	    if (navId !== navVersion) return;
158	    if (isEntrancePlayed) return;
159	    isEntrancePlayed = true;
160	    if (playEntrance !== false) { triggerSceneEnter(index); }
161	    else { forceSceneFinalState(index); }
162	  }
163	
164	  function completeCallback() {
165	    if (navId !== navVersion) return;
166	    if (settled) return;
167	    settled = true;
168	    fromEl.classList.remove('is-leaving');
169	    targetEl.classList.remove('is-entering');
170	    setActiveScene(index);
171	    currentScene = index;
172	    currentNavTimeline = null;
173	    updateProgress();
174	  }
175	
176	  if (playEntrance === false) {
177	    // Instant/final state — used by audit
178	    gsap.killTweensOf(camera);
179	    camera.x = camTarget.x; camera.y = camTarget.y; camera.z = finalZ; camera.r = s.r || 0;
180	    applyCameraTransform();
181	    fromEl.classList.remove('is-leaving');
182	    targetEl.classList.remove('is-entering');
183	    setActiveScene(index);
184	    currentScene = index;
185	    forceSceneFinalState(index);
186	    updateProgress();
187	    return;
188	  }
189	
190	  var dur = reduceMotion ? 0.001 : (s.d || 1.5);
191	
192	  // Mark states
193	  fromEl.classList.add('is-leaving');
194	  targetEl.classList.add('is-entering');
195	
196	  currentNavTimeline = gsap.timeline({onComplete: completeCallback});
197	
198	  // Departure fade: from scene over first 30%
199	  if (!reduceMotion) {
200	    currentNavTimeline.to(fromEl, {opacity:0, duration:dur*0.30, ease:'power2.in'}, 0);
201	  } else {
202	    gsap.set(fromEl, {opacity:0});
203	  }
204	
205	  // Camera movement: full duration
206	  currentNavTimeline.to(camera, {
207	    x: camTarget.x, y: camTarget.y, z: finalZ, r: s.r || 0,
208	    duration: dur, ease: 'power3.inOut',
209	    onUpdate: applyCameraTransform
210	  }, 0);
211	
212	  // Entrance trigger
213	  var entranceTime = reduceMotion ? 0 : (isImpactScene(index) ? dur : dur * 0.80);
214	  currentNavTimeline.addLabel('sceneEnter', entranceTime);
215	  currentNavTimeline.call(entranceCallback, null, 'sceneEnter');
216	}
217	
218	function nextScene() { goToScene(currentScene + 1); }
219	function prevScene() { goToScene(currentScene - 1); }
220	function firstScene() { goToScene(0); }
221	function lastScene() { goToScene(scenes.length - 1); }
222	
223	function updateProgress() {
224	  if (progressFill) {
225	    progressFill.style.width = ((currentScene + 1) / scenes.length * 100) + '%';
226	  }
227	}
