229	/* ===== SCENE LIFECYCLE ===== */
230	function triggerSceneEnter(index) {
231	  var scene = scenes[index];
232	  var el = document.getElementById('scene-' + scene.id);
233	  if (!el) return;
234	
235	  var fnName = 'enter_' + scene.id.replace(/-/g,'_');
236	  if (typeof window[fnName] === 'function') {
237	    window[fnName](el);
238	  } else {
239	    var children = el.querySelectorAll(':scope > .scene-inner > *');
240	    gsap.to(children, {opacity:1,y:0,duration:0.5,stagger:0.03,ease:'power2.out',delay:0.1});
241	  }
242	
243	  if (particleScenes.indexOf(index) >= 0) { startParticles(); }
244	  else { stopParticles(); }
245	
246	  if (index === 18) { startTypewriter(); }
247	
248	  if (index === 31) {
249	    var fq = document.getElementById('final-question-text');
250	    if (fq) { animateWordFade(fq, 350); }
251	  }
252	
253	  if (index === 33) {
254	    var fqEl = document.querySelector('#scene-choose-questions .fq-main');
255	    if (fqEl) { gsap.fromTo(fqEl, {textShadow:'0 0 0px rgba(255,184,0,0)'}, {textShadow:'0 0 40px rgba(255,184,0,0.3)',duration:1.5,ease:'power2.out'}); }
256	  }
257	
258	}
259	
260	
261	function triggerSceneLeave(index) {
262	  var scene = scenes[index];
263	  var el = document.getElementById('scene-' + scene.id);
264	  if (particleScenes.indexOf(index) >= 0) { stopParticles(); }
265	  if (index === 21 && connCtx) { connCtx.clearRect(0,0,connCanvas.width,connCanvas.height); connDrawn = false; }
266	}
