268	var particleScenes = [0, 21];
269	
270	/* ===== PREPARE SCENE ENTER (set initial states before visibility) ===== */
271	function resetTypewriter() {
272	  typewriterDone = false;
273	  var target = document.getElementById('typewriter-target');
274	  if (target) target.textContent = '';
275	}
