278	  var el = document.getElementById('scene-' + scenes[index].id);
279	  if (!el) return;
280	
281	  if (index === 18) { resetTypewriter(); }
282	  if (index === 21) {
283	    if (connCtx) { connCtx.clearRect(0,0,connCanvas.width,connCanvas.height); }
284	    connDrawn = false;
285	  }
286	
287	  switch (scenes[index].id) {
288	    case 'title':
289	      gsap.set(el.querySelectorAll('.s-line'), {y:30,opacity:0});
290	      gsap.set(el.querySelector('.s-sub'), {opacity:0});
291	      break;
