299	      gsap.set(el.querySelectorAll('.limit-item'), {scale:0.5,opacity:0});
300	      break;
301	    case 'bottleneck':
302	      gsap.set(el.querySelector('.b-old'), {opacity:0});
303	      gsap.set(el.querySelectorAll('.b-items span'), {x:-20,opacity:0});
304	      break;
305	    case 'asking-judging-acting':
306	      gsap.set(el.querySelectorAll('.s-statement'), {y:15,opacity:0});
307	      break;
308	    case 'worried-overconfident':
309	      gsap.set(el.querySelector('.split-worried'), {x:-100,opacity:0});
310	      gsap.set(el.querySelector('.split-over'), {x:100,opacity:0});
311	      break;
312	    case 'which-part-cheap':
313	      gsap.set(el.querySelector('.s-bigquestion'), {scale:0.3,opacity:0});
314	      break;
315	    case 'rs-5000': case '7-days': case 'rs-1000':
316	      gsap.set(el.querySelector('.big-number'), {scale:0.2,opacity:0});
