318	    case 'challenge-overview':
319	      gsap.set(el.querySelectorAll('.ct-item'), {scale:0.5,opacity:0});
320	      gsap.set(el.querySelector('.s-question-sm'), {opacity:0});
321	      break;
322	    case 'nouns':
323	      gsap.set(el.querySelectorAll('.nouns-list span'), {x:-20,opacity:0});
324	      break;
325	    case 'questions':
326	      gsap.set(el.querySelectorAll('.questions-list span'), {x:20,opacity:0});
