328	    case 'execution-quote':
329	      gsap.set(el.querySelector('.quote-card'), {scale:0.8,opacity:0});
330	      break;
331	    case 'direction-missing':
332	      gsap.set(el.querySelector('.quote-card'), {y:20,opacity:0});
333	      break;
334	    case 'ai-ecosystem':
335	      gsap.set(el.querySelectorAll('.tool-node'), {scale:0.3,opacity:0});
