834	  particleActive = false;
835	  particleCanvas.classList.remove('active');
836	  if (pRaf) { cancelAnimationFrame(pRaf); pRaf = null; }
837	  pCtx.clearRect(0, 0, particleCanvas.width, particleCanvas.height);
838	}
