912	    prevScene();
913	  }
914	  if (e.key === 'Home') { e.preventDefault(); firstScene(); }
915	  if (e.key === 'End') { e.preventDefault(); lastScene(); }
916	  if (e.key === 'o' || e.key === 'O') {
917	    e.preventDefault();
918	    if (overviewActive) { exitOverview(); } else { enterOverview(); }
919	  }
920	  if (e.key === 'f' || e.key === 'F') {
921	    e.preventDefault();
