111	/* ===== SCENE STATE MANAGEMENT ===== */
112	function setActiveScene(index) {
113	  document.querySelectorAll('.scene').forEach(function(el) {
114	    el.classList.remove('is-active', 'is-entering', 'is-leaving');
115	    el.style.opacity = '';
116	  });
