}

/* Viewport with 3D Perspective */
#viewport {
  position:fixed;
  inset:0;
  overflow:hidden;
  perspective:2000px; /* Increased for deeper 3D space */
  perspective-origin: center center;
  background:var(--bg);
  overflow-x: hidden;
  overflow-y: hidden;
}

/* World Container - True 3D Space */
#world {
  position:absolute;
  top:50%;
  left:50%;
  width:1px;
  height:1px;
  transform-origin:0 0;
  will-change:transform;
  backface-visibility:hidden;
  transform-style: preserve-3d;
}

/* Parallax Layers with Depth */
.parallax-layer {
  position:fixed;
  inset:0;
  pointer-events:none;
  z-index:0;
  will-change:transform;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

/* Enhanced Scene Base */
.scene {
  position:absolute;
  transform:translate(-50%,-50%) translateZ(0px);
  z-index:10;
  visibility:hidden;
  pointer-events:none;
  backface-visibility:hidden;
}
