  gap:1.5rem;
  margin-top:1.5rem;
}

.b-old {
  font-size:3.2rem;
  font-weight:700;
  color:var(--text-muted);
  text-decoration:line-through;
  opacity:0.6;
  position:relative;
}

.b-arrow {
  font-size:2.4rem;
  color:var(--gold);
  animation:bounceArrow 2.5s ease-in-out infinite;
  text-shadow:0 0 8px rgba(255,184,0,0.3);
}

@keyframes bounceArrow {
  0%,100%{transform:translateY(0) scale(1);}
  30%{transform:translateY(-8px) scale(1.1);}
  50%{transform:translateY(4px) scale(0.95);}
  70%{transform:translateY(-4px) scale(1.05);}
  100%{transform:translateY(0) scale(1);}
}

.b-now {
  font-size:1.5rem;
  color:var(--gold);
  font-weight:600;
  letter-spacing:-0.005em;
}

.b-items {
  display:flex;
  gap:1.8rem;
  margin-top:1rem;
}

.b-items span {
  font-size:2.8rem;
  font-weight:800;
  padding:1rem 1.8rem;
  background:var(--glass);
  border-radius:14px;
  border:1px solid var(--glass-light);
  transition:all 0.3s ease;
  backdrop-filter: blur(10px);
}

.b-items span:hover {
  transform:translateY(-3px) scale(1.03);
  box-shadow:0 8px 20px rgba(0,0,0,0.15);
}

.b-items .b-ask {
  color:var(--cyan);
  border-left:4px solid var(--cyan);
  box-shadow:0 0 25px rgba(34,211,238,0.1);
}

.b-items .b-judge {
  color:var(--violet);
  border-left:4px solid var(--violet);
  box-shadow:0 0 25px rgba(139,92,246,0.1);
}

.b-items .b-act {
  color:var(--green);
  border-left:4px solid var(--green);
  box-shadow:0 0 25px rgba(34,197,94,0.1);
}

/* SPLIT VIEW - ENHANCED */
.split-view {
  display:flex;
  gap:0;
  border-radius:20px;
  overflow:hidden;
  box-shadow:0 8px 32px rgba(0,0,0,0.25);
}

.split-side {
  flex:1;
  padding:3rem 2.5rem;
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:1.2rem;
  min-width:360px;
  transition:all 0.4s ease;
}

.split-worried {
  background:rgba(239,68,68,0.08);
  border-right:1px solid rgba(255,255,255,0.06);
}

.split-worried:hover {
  background:rgba(239,68,68,0.12);
}

.split-over {
  background:rgba(34,197,94,0.06);
}

.split-over:hover {
  background:rgba(34,197,94,0.09);
}

.split-label {
  font-size:1.1rem;
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:0.12em;
}

.split-worried .split-label {
  color:var(--red);
  text-shadow:0 0 8px rgba(239,68,68,0.2);
}

.split-over .split-label {
  color:var(--green);
  text-shadow:0 0 8px rgba(34,197,94,0.2);
}

.split-person-visual {
  width:320px;
  height:260px;
  border-radius:20px;
  overflow:hidden;
  position:relative;
  isolation:isolate;
  background:var(--glass);
  border:1px solid var(--glass-light);
}

.split-person-visual img {
  width:100%;
  height:100%;
  display:block;
  object-fit:cover;
  transition:transform 0.5s ease;
}

.split-person-image:hover .split-person-visual img {
  transform:scale(1.03);
}

.split-person-overlay {
  position:absolute;
  inset:0;
  pointer-events:none;
  background:linear-gradient(180deg,rgba(7,11,23,0.02),rgba(7,11,23,0.45));
}

.split-person-visual.image-failed {
  background:var(--glass);
}

.split-person-visual.image-failed img {
  display:none;
}

.split-thought {
  font-size:1.4rem;
  color:var(--text-secondary);
  font-style:italic;
  max-width:280px;
  line-height:1.4;
}

.split-tag {
  font-size:0.9rem;
  font-weight:600;
  opacity:0.7;
  letter-spacing:-0.005em;
}

/* PROMPT CARDS - PREMIUM */
.prompt-card {
  background:linear-gradient(145deg,rgba(255,255,255,0.04),rgba(255,255,255,0.01));
  border-radius:18px;
  padding:2.5rem;
  min-width:560px;
  max-width:750px;
  border:1px solid var(--glass-light);
  backdrop-filter: blur(16px);
  box-shadow:0 15px 35px rgba(0,0,0,0.2);
  transition:all 0.4s ease;
}

.prompt-card:hover {
  transform:translateY(-3px) scale(1.01);
  box-shadow:0 20px 45px rgba(0,0,0,0.25);
}

.prompt-generic {
  border:1px solid rgba(148,163,184,0.15);
}

.prompt-contextual {
  border:1px solid rgba(6,182,212,0.25);
  box-shadow:0 0 30px rgba(6,182,212,0.08);
}

.prompt-label {
  font-size:0.9rem;
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:0.1em;
  margin-bottom:1.2rem;
  text-shadow:0 1px 2px rgba(0,0,0,0.1);
}

.prompt-label.generic {
  color:var(--text-muted);
}

.prompt-label.contextual {
  color:var(--cyan);
  text-shadow:0 0 8px rgba(6,182,212,0.2);
}

.prompt-text {
  font-size:1.5rem;
  color:var(--text-secondary);
  font-weight:300;
  line-height:1.7;
  font-style:italic;
  max-width:600px;
}

.prompt-result {
  font-size:1.25rem;
  margin-top:1.2rem;
  padding:1rem 1.3rem;
  border-radius:10px;
  font-weight:500;
  letter-spacing:-0.005em;
}

.prompt-generic .prompt-result {
  background:rgba(255,255,255,0.04);
  border:1px solid rgba(255,255,255,0.08);
}

.prompt-contextual .prompt-result {
  background:rgba(6,182,212,0.05);
  border-left:3px solid var(--cyan);
  color:var(--text-primary);
}

/* TOOL CONSTELLATION - ENHANCED */
.constellation {
  position:relative;
  width:1400px;
  height:950px;
  margin:0 auto;
  perspective:1000px;
}

#scene-ai-ecosystem .constellation {
  margin:0;
  padding:4rem;
}

#scene-ai-ecosystem .constellation-center {
  position:absolute;
  left:50%;
  top:50%;
  transform:translate(-50%,-50%) rotateY(0deg) rotateX(0deg);
  z-index:3;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  width:min(800px,75%);
  text-align:center;
  pointer-events:none;
  transition:all 0.6s ease;
}

#scene-ai-ecosystem .constellation-center:hover {
  transform:translate(-50%,-50%) rotateY(5deg) rotateX(-3deg) scale(1.02);
}

#scene-ai-ecosystem .constellation-center .slide-label {
  margin-bottom:1.2rem;
}

#scene-ai-ecosystem .constellation-center .s-heading {
  margin:0;
  max-width:800px;
  line-height:1.12;
}

#scene-ai-ecosystem .constellation-origin {
  position:absolute;
  left:50%;
  top:50%;
  width:0;
  height:0;
  z-index:2;
}

#connections-canvas {
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  pointer-events:none;
  z-index:0;
}

.tool-node {
  position:absolute;
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:0.8rem;
  cursor:pointer;
  z-index:2;
  opacity:0;
  transform:translate(-50%,-50%) scale(0.8);
  transition:all 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  backdrop-filter: blur(8px);
  background:rgba(17,24,39,0.6);
  border:1px solid rgba(255,255,255,0.08);
  border-radius:16px;
  padding:0.8rem;
  box-shadow:0 4px 16px rgba(0,0,0,0.2);
}

.tool-node:hover {
  transform:translate(-50%,-50%) scale(1.05) rotate(2deg);
  border-color:var(--gold);
  box-shadow:0 8px 24px rgba(0,0,0,0.25), 0 0 16px rgba(255,184,0,0.15);
}

.tool-node .tn-icon {
  width:90px;
  height:90px;
  border-radius:20px;
  display:flex;
  align-items:center;
  justify-content:center;
  border:1px solid rgba(255,255,255,0.1);
  background:rgba(17,24,39,0.8);
  transition:all 0.4s ease;
}

.tool-node:hover .tn-icon {
  border-color:var(--gold);
  box-shadow:0 0 20px rgba(255,184,0,0.2);
  background:rgba(255,184,0,0.05);
}

.tool-node .tn-name {
  font-size:1.6rem;
  font-weight:700;
  color:var(--text-primary);
  white-space:nowrap;
  letter-spacing:-0.005em;
  text-shadow:0 1px 2px rgba(0,0,0,0.1);
}

.tool-node .tn-cap {
  font-size:1.2rem;
  font-weight:500;
  color:var(--text-secondary);
  white-space:nowrap;
  letter-spacing:-0.003em;
}

/* 10/10 DISPLAY - ENHANCED */
.ten-display {
  display:flex;
  align-items:baseline;
  gap:1rem;
  margin:0.8rem 0;
}

.ten-number {
  font-size:clamp(5rem, 9vw, 8rem);
  font-weight:900;
  color:var(--gold);
  line-height:1;
  text-shadow:0 0 12px rgba(255,184,0,0.15);
}

.ten-label {
  font-size:1.8rem;
  color:var(--text-muted);
  font-weight:300;
  letter-spacing:-0.005em;
}

/* SPOTLIGHT CARDS - PREMIUM GLASS */
.spotlight-card {
  background:linear-gradient(145deg,rgba(255,255,255,0.04),rgba(255,255,255,0.01));
  border-radius:20px;
  padding:3rem;
  text-align:center;
  min-width:650px;
  border:1px solid var(--glass-light);
  backdrop-filter: blur(18px);
  box-shadow:0 15px 35px rgba(0,0,0,0.25);
  position:relative;
  overflow:hidden;
  transition:all 0.4s ease;
}

.spotlight-card:hover {
  transform:translateY(-4px) scale(1.01);
  box-shadow:0 20px 45px rgba(0,0,0,0.3);
}

.spotlight-card::before {
  content: '';
  position:absolute;
  top:0;
  left:-100%;
  width:200%;
  height:100%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,0.1),transparent);
  transition:left 0.8s ease;
}

.spotlight-card:hover::before {
  left:0;
}

.spotlight-card .sp-tag {
  font-size:1rem;
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:0.1em;
  padding:0.5rem 1.2rem;
  border-radius:12px;
  display:inline-block;
  margin-bottom:1.4rem;
  font-weight:600;
}

.sp-design .sp-tag {
  color:var(--violet);
  background:rgba(139,92,246,0.1);
  box-shadow:0 0 15px rgba(139,92,246,0.1);
}

.sp-code .sp-tag {
  color:var(--cyan);
  background:rgba(34,211,238,0.1);
  box-shadow:0 0 15px rgba(34,211,238,0.1);
}

.sp-multi .sp-tag {
  color:var(--gold);
  background:rgba(255,184,0,0.1);
  box-shadow:0 0 15px rgba(255,184,0,0.1);
}

.spotlight-card h3 {
  font-size:2.6rem;
  font-weight:700;
  margin-bottom:1rem;
  letter-spacing:-0.008em;
}

.spotlight-card p {
  font-size:1.6rem;
  color:var(--text-secondary);
  font-weight:300;
  line-height:1.6;
  max-width:700px;
}

/* CHALLENGE TRIANGLE - ENHANCED */
.challenge-triangle {
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:2.5rem;
  align-items:center;
  margin-top:2rem;
}

.ct-item {
  text-align:center;
  padding:1.8rem 2.5rem;
  border-radius:18px;
  background:linear-gradient(145deg,rgba(255,255,255,0.04),rgba(255,255,255,0.01));
  border:1px solid var(--glass-light);
  backdrop-filter: blur(14px);
  box-shadow:0 8px 24px rgba(0,0,0,0.15);
  transition:all 0.4s ease;
  position:relative;
  overflow:hidden;
}

.ct-item:hover {
  transform:translateY(-3px) scale(1.02);
  box-shadow:0 12px 28px rgba(0,0,0,0.2);
}

.ct-item p {
  font-size:1.2rem;
  color:var(--text-muted);
  margin-top:0.5rem;
  line-height:1.4;
}

.ct-top {
  grid-column:1/-1;
  margin-bottom:1.5rem;
}

.ct-gold {
  border:1px solid rgba(255,184,0,0.25);
  box-shadow:0 0 20px rgba(255,184,0,0.08);
}

.ct-gold::before {
  content: '';
  position:absolute;
  top:0;
  left:0;
  width:100%;
  height:4px;
  background:linear-gradient(90deg,transparent,var(--gold),transparent);
  transform:scaleX(0);
  transition:transform 0.5s ease;
}

.ct-gold:hover::before {
  transform:scaleX(1);
}

.ct-cyan {
  border:1px solid rgba(6,182,212,0.25);
  box-shadow:0 0 20px rgba(6,182,212,0.08);
}

.ct-cyan::before {
  content: '';
  position:absolute;
  top:0;
  left:0;
  width:100%;
  height:4px;
  background:linear-gradient(90deg,transparent,var(--cyan),transparent);
  transform:scaleX(0);
  transition:transform 0.5s ease;
}

.ct-cyan:hover::before {
  transform:scaleX(1);
}

.ct-green {
  border:1px solid rgba(16,185,129,0.25);
  box-shadow:0 0 20px rgba(16,185,129,0.08);
}

.ct-green::before {
  content: '';
  position:absolute;
  top:0;
  left:0;
  width:100%;
  height:4px;
  background:linear-gradient(90deg,transparent,var(--green),transparent);
  transform:scaleX(0);
  transition:transform 0.5s ease;
}

.ct-green:hover::before {
  transform:scaleX(1);
}

.ct-gold .big-number-sm {
  color:var(--gold);
}

.ct-cyan .big-number-sm {
  color:var(--cyan);
}

.ct-green .big-number-sm {
  color:var(--green);
}

/* NOUN LIST - ENHANCED */
.nouns-list {
  display:flex;
  flex-direction:column;
  gap:0.7rem;
  align-items:center;
}

.nouns-list span {
  font-size:2.6rem;
  font-weight:300;
  color:#64758B;
  letter-spacing:-0.005em;
  text-shadow:0 1px 2px rgba(0,0,0,0.1);
  transition:all 0.3s ease;
}

.nouns-list span:hover {
  transform:scale(1.05);
  color:var(--text-primary);
  text-shadow:0 0 8px rgba(255,255,255,0.2);
}

/* QUESTION LIST - ENHANCED */
.questions-list {
  display:flex;
  flex-direction:column;
  gap:1rem;
  align-items:flex-start;
}

.questions-list span {
  font-size:1.8rem;
  font-weight:400;
  padding:0.5rem 0;
  line-height:1.5;
  color:var(--text-secondary);
  background:var(--glass);
  padding:0.8rem 1.2rem;
  border-radius:10px;
  border:1px solid var(--glass-light);
  transition:all 0.3s ease;
}

.questions-list span:hover {
  background:rgba(255,184,0,0.05);
  color:var(--text-primary);
  transform:translateX(4px);
}

/* EQUATION DISPLAY (DANGER) - ENHANCED */
.equation-display {
  display:flex;
  align-items:center;
  gap:1.2rem;
  justify-content:center;
  margin-top:1.5rem;
}

.eq-part {
  font-size:clamp(6rem, 10vw, 8rem);
  font-weight:900;
  letter-spacing:-0.02em;
  line-height:1;
}

.eq-one {
  color:var(--text-primary);
  text-shadow:0 0 8px rgba(255,255,255,0.15);
}

.eq-op {
  font-size:clamp(3.5rem, 6vw, 4.5rem);
  color:var(--red);
  opacity:0.6;
  text-shadow:0 0 6px rgba(239,68,68,0.2);
}

.eq-tenk {
  color:var(--red);
  text-shadow:0 0 15px rgba(239,68,68,0.3);
  position:relative;
}

.eq-tenk::after {
  content: '';
  position:absolute;
  bottom:-8px;
  left:50%;
  transform:translateX(-50%);
  width:70%;
  height:3px;
  background:linear-gradient(90deg,transparent,var(--red),transparent);
  border-radius:2px;
  opacity:0.6;
}

.eq-caption {
  font-size:1.6rem;
  color:var(--text-muted);
  font-weight:300;
  margin-top:1.2rem;
  max-width:700px;
}

.danger-grid {
  display:flex;
  flex-wrap:wrap;
  gap:1.4rem;
  justify-content:center;
  margin-top:1.8rem;
  width:100%;
}

.d-node {
  display:flex;
  align-items:center;
  gap:0.9rem;
  padding:1rem 1.6rem;
  border-radius:12px;
  font-size:1.4rem;
  color:var(--text-secondary);
  background:linear-gradient(145deg,rgba(255,255,255,0.04),rgba(255,255,255,0.01));
  border:1px solid var(--glass-light);
  backdrop-filter: blur(10px);
  transition:all 0.3s ease;
  position:relative;
  overflow:hidden;
}

.d-node:hover {
  transform:translateY(-3px) scale(1.03);
  box-shadow:0 8px 20px rgba(0,0,0,0.15);
}

.d-node .d-icon {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:28px;
  height:28px;
}

.d-node .d-icon svg {
  width:20px;
  height:20px;
}

.d-node.d-hallucination {
  border:1px solid rgba(239,68,68,0.3);
  background:linear-gradient(145deg,rgba(239,68,68,0.05),rgba(239,68,68,0.02));
}

.d-node.d-security {
  border:1px solid rgba(249,115,22,0.3);
  background:linear-gradient(145deg,rgba(249,115,22,0.05),rgba(249,115,22,0.02));
}

.d-node.d-scaling {
  border:1px solid rgba(239,68,68,0.3);
  background:linear-gradient(145deg,rgba(239,68,68,0.05),rgba(239,68,68,0.02));
}

.d-node.d-confidence {
  border:1px solid rgba(249,115,22,0.3);
  background:linear-gradient(145deg,rgba(249,115,22,0.05),rgba(249,115,22,0.02));
}

/* UPDATE STACK - ENHANCED */
.update-stack {
  display:flex;
  flex-direction:column;
  gap:1.2rem;
  align-items:center;
}

.update-item {
  font-size:3rem;
  font-weight:500;
  color:var(--text-secondary);
  line-height:1.4;
  letter-spacing:-0.005em;
  text-align:center;
  max-width:700px;
  padding:0.8rem 1.5rem;
  background:var(--glass);
  border-radius:12px;
  border:1px solid var(--glass-light);
  transition:all 0.3s ease;
}

.update-item:hover {
  transform:translateY(-3px) scale(1.02);
  box-shadow:0 8px 20px rgba(0,0,0,0.15);
}

/* RESPONSIVE - OPTIMIZED FOR LARGE SCREENS */
@media (max-width:1920px) {
  .scene-inner {
    min-width:480px;
    max-width:900px;
    padding:2.5rem;
  }
  h1,.s-title {
    font-size:4rem!important;
  }
  .s-question {
    font-size:2.8rem;
  }
  .s-bigquestion {
    font-size:4rem;
  }
  .big-number {
    font-size:5rem;
  }
  .big-number-sm {
    font-size:3.5rem;
  }
  .s-heading {
    font-size:2.2rem;
  }
  .s-statement {
    font-size:1.8rem;
  }
  .s-question-sm {
    font-size:2rem;
  }
  .final-question {
    font-size:4.5rem;
  }
  .final-block .fq-main {
    font-size:3rem;
  }
  .thank-you-text {
    font-size:4rem;
  }
  .quote-card .q-main {
    font-size:2.2rem;
  }
  .limits-grid {
    flex-wrap:wrap;
    justify-content:center;
  }
  .limits-grid .limit-item {
    flex-basis:45%;
  }
  .b-items {
    flex-direction:column;
    align-items:center;
  }
  .b-items span {
    font-size:2rem;
  }
  .constellation {
    width:800px;
    height:600px;
  }
  .tool-node .tn-icon {
    width:56px;
    height:56px;
  }
  .tool-node .tn-icon svg {
    width:28px;
    height:28px;
  }
  .tool-node .tn-name {
    font-size:1.1rem;
  }
  .tool-node .tn-cap {
    font-size:0.85rem;
  }
  .ten-number {
    font-size:4.5rem;
  }
  .eq-part {
    font-size:5rem;
  }
  .split-view {
    flex-direction:column;
  }
  .split-side {
    min-width:auto;
  }
  .nouns-list span {
    font-size:2rem;
  }
  .questions-list span {
    font-size:1.3rem;
  }
  .prompt-card {
    min-width:360px;
    max-width:500px;
  }
  .spotlight-card {
    min-width:400px;
  }
  .d-node {
    font-size:1.1rem;
  }
  .update-item {
    font-size:2rem;
  }
  .eq-part {
    font-size:6rem;
