    height:38px;
  }
  .tool-node .tn-icon svg {
    width:18px;
    height:18px;
  }
  .tool-node .tn-name {
    font-size:0.85rem;
  }
  .tool-node .tn-cap {
    display:none;
  }
  .ten-number {
    font-size:2.5rem;
  }
  .eq-part {
    font-size:2.8rem;
  }
  .final-question {
    font-size:2.5rem;
  }
  .final-block .fq-main {
    font-size:1.8rem;
  }
  .thank-you-text {
    font-size:2.5rem;
  }
  .prompt-card {
    min-width:220px;
    max-width:320px;
  }
  .spotlight-card {
    min-width:250px;
  }
  .d-node {
    font-size:0.8rem;
  }
  .update-item {
    font-size:1.4rem;
  }
  #hud {
    bottom:1rem;
    gap:0.6rem;
  }
  #progress-bar {
    width:50px;
  }
  .zl-item {
    font-size:0.8rem;
    padding:0.25rem 0.8rem;
  }
  .d-node {
    font-size:0.75rem;
  }
  .limit-visual {
    width:90px;
    height:90px;
  }
}

/* REDUCED MOTION - ENHANCED */
@media (prefers-reduced-motion:reduce) {
  *,*::before,*::after {
    animation-duration:0.01ms!important;
    transition-duration:0.01ms!important;
  }
  .gold-line::after {
    animation:none;
    background:var(--gold);
  }
  .b-arrow {
    animation:none;
  }
  .final-question::after {
    animation:none;
    background:linear-gradient(90deg,transparent,var(--gold),transparent);
    opacity:0.4;
  }
  .thank-you-text::after {
    animation:none;
    background:linear-gradient(90deg,transparent,var(--gold),transparent);
    opacity:0.3;
  }
}

/* PRINT STYLES - BASIC */
@media print {
  body {
    background:white;
    color:black;
  }
  .scene-inner {
    background:white;
    border:1px solid #ddd;
    box-shadow:none;
  }
  .text-gold, .text-cyan, .text-violet {
    color:black;
  }
  .gold-line {
    background:#ddd;
  }
}

