:root {
  /* Enhanced Color Palette for Premium Feel */
  --bg: #020408; /* Deeper black for true cinema feel */
  --deep-navy: #030712; /* Even darker navy */
  --surface: rgba(17, 24, 39, 0.82); /* More transparent for glass effect */
  --surface-elevated: rgba(31, 41, 55, 0.85); /* Elevated glass */
  --glass: rgba(255, 255, 255, 0.03); /* Pure glass effect */
  --glass-light: rgba(255, 255, 255, 0.06); /* Lighter glass */

  /* Refined Accent Colors */
  --gold: #FFB800;
  --gold-bright: #FFD54A;
  --gold-glow: #FFE066;

  --cyan: #06B6D4; /* More vibrant cyan */
  --cyan-bright: #67E8F9;
  --cyan-glow: #A7F3D0;

  --violet: #8B5CF6;
  --violet-bright: #A78BFA;
  --violet-glow: #C4B5FD;

  --green: #10B981; /* Emerald green */
  --green-bright: #34D399;
  --green-glow: #6EE7B7;

  --orange: #F97316;
  --orange-bright: #FB923C;
  --orange-glow: #FDBA74;

  --red: #EF4444;
  --red-bright: #F87171;
  --red-glow: #FCA5A5;

  --blue: #3B82F6;
  --blue-bright: #60A5FA;
  --blue-glow: #93C5FD;

  --text-primary: #FFFFFF;
  --text-secondary: #E5E7EB; /* Lighter for better readability */
  --text-muted: #9CA3AF;
  --text-dim: #6B7280;

  /* Glow Effects */
  --glow-gold: 0 0 30px rgba(255, 184, 0, 0.4), 0 0 60px rgba(255, 184, 0, 0.2);
  --glow-cyan: 0 0 30px rgba(6, 182, 212, 0.4), 0 0 60px rgba(6, 182, 212, 0.2);
  --glow-violet: 0 0 30px rgba(139, 92, 246, 0.4), 0 0 60px rgba(139, 92, 246, 0.2);
  --glow-green: 0 0 30px rgba(16, 185, 129, 0.4), 0 0 60px rgba(16, 185, 129, 0.2);
  --glow-red: 0 0 30px rgba(239, 68, 68, 0.4), 0 0 60px rgba(239, 68, 68, 0.2);
}

/* Base Styles - Enhanced for 75" Screen */
* {
  margin:0;
  padding:0;
  box-sizing:border-box;
}
html, body {
  width:100%;
  height:100%;
  overflow:hidden;
  background:var(--bg);
  font-family:'Inter',sans-serif;
  color:var(--text-primary);
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
  text-rendering: optimizeLegibility;
}

/* Viewport with 3D Perspective */
#viewport {
  position:fixed;
  inset:0;
  overflow:hidden;
  perspective:2000px; /* Increased for deeper 3D space */
  perspective-origin: center center;
  background:var(--bg);
  overflow-x: hidden;
  overflow-y: hidden;
}

/* World Container - True 3D Space */
#world {
  position:absolute;
  top:50%;
  left:50%;
  width:1px;
  height:1px;
  transform-origin:0 0;
  will-change:transform;
  backface-visibility:hidden;
  transform-style: preserve-3d;
}

/* Parallax Layers with Depth */
.parallax-layer {
  position:fixed;
  inset:0;
  pointer-events:none;
  z-index:0;
  will-change:transform;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

/* Enhanced Scene Base */
.scene {
  position:absolute;
  transform:translate(-50%,-50%) translateZ(0px);
  z-index:10;
  visibility:hidden;
  pointer-events:none;
  backface-visibility:hidden;
}
.scene.is-active {
  visibility:visible;
  pointer-events:auto;
}
.scene.is-entering {
  visibility:visible;
  pointer-events:none;
}
.scene.is-leaving {
  visibility:visible;
  pointer-events:none;
}
.scene.is-measuring {
  visibility:hidden;
  pointer-events:none;
}

/* Enhanced Scene Inner with Glassmorphism */
.scene-inner {
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  text-align:center;
  padding:3.5rem; /* Increased for 75" readability */
  min-width:600px;
  max-width:1100px;
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  background: var(--glass);
  border: 1px solid var(--glass-light);
  border-radius: 24px;
  box-shadow:
    0 8px 32px rgba(0, 0, 0, 0.37),
    inset 0 0 0 1px rgba(255, 255, 255, 0.05);
  position: relative;
  overflow: hidden;
  isolation: isolate;
}

/* Subtle animated background pattern */
.scene-inner::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background:
    radial-gradient(circle at 20% 30%, rgba(255,184,0,0.03) 0%, transparent 20%),
    radial-gradient(circle at 80% 70%, rgba(6,182,212,0.03) 0%, transparent 20%),
    radial-gradient(circle at 40% 40%, rgba(139,92,246,0.02) 0%, transparent 30%);
  pointer-events: none;
  z-index: -1;
  animation: subtleShift 20s ease-in-out infinite;
}

@keyframes subtleShift {
  0%, 100% { background-position: 0% 0%; }
  50% { background-position: 100% 100%; }
}

/* TYPOGRAPHY - OPTIMIZED FOR 75" DISTANCE VIEWING */
h1, h2, h3 {
  font-family:'Inter',sans-serif;
  text-transform:none;
  letter-spacing:-0.015em;
  line-height:1.2;
  color:var(--text-primary);
  text-rendering: geometricPrecision;
}

/* Dynamic font sizing based on viewport for 75" optimization */
h1 {
  font-size: clamp(4.5rem, 8vw, 9rem);
  font-weight:900;
  text-shadow:
    0 2px 4px rgba(0,0,0,0.3),
    0 0 10px rgba(255,255,255,0.1);
}

h2 {
  font-size: clamp(3.2rem, 6vw, 7rem);
  font-weight:700;
  letter-spacing:-0.01em;
}

h3 {
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight:600;
}

p {
  font-size: clamp(1.5rem, 3vw, 2.2rem);
  font-weight:300;
  line-height:1.6;
  color:var(--text-secondary);
  max-width: 800px;
}

/* TEXT COLOR UTILITIES - WITH GLOW OPTIONS */
.text-glow {
  text-shadow: var(--glow-gold);
}
.text-glow-cyan {
  text-shadow: var(--glow-cyan);
}
.text-glow-violet {
  text-shadow: var(--glow-violet);
}
.text-glow-green {
  text-shadow: var(--glow-green);
}
.text-glow-red {
  text-shadow: var(--glow-red);
}

.text-gold { color:var(--gold) !important; }
.text-cyan { color:var(--cyan) !important; }
.text-violet { color:var(--violet) !important; }
.text-blue { color:var(--blue) !important; }
.text-pink { color:var(--pink) !important; }
.text-green { color:var(--green) !important; }
.text-orange { color:var(--orange) !important; }
.text-red { color:var(--red) !important; }
.text-primary { color:var(--text-primary) !important; }
.text-secondary { color:var(--text-secondary) !important; }
.text-muted { color:var(--text-muted) !important; }
.text-dim { color:var(--text-dim) !important; }

/* ENHANCED GRADIENT TEXT */
.gradient-gold {
  background:linear-gradient(135deg,var(--gold),var(--gold-bright),var(--orange));
  -webkit-background-clip:text;
  background-clip:text;
  color:transparent;
  filter: drop-shadow(0 0 8px rgba(255,184,0,0.3));
}

.gradient-white-gold {
  background:linear-gradient(135deg,#FFF,var(--gold));
  -webkit-background-clip:text;
  background-clip:text;
  color:var(--gold);
}

.gradient-cyan-violet {
  background:linear-gradient(135deg,var(--cyan),var(--violet));
  -webkit-background-clip:text;
  background-clip:text;
  color:transparent;
  filter: drop-shadow(0 0 6px rgba(6,182,212,0.25));
}

