/* GOLD LINE / DIVIDER - WITH ANIMATION */
.gold-line {
  width:100px;
  height:5px;
  background:var(--gold);
  border-radius:3px;
  margin:2rem 0;
  position:relative;
  overflow:hidden;
  transition: all 0.4s ease;
}

.gold-line:hover {
  width: 140px;
  transform: scaleX(1.05);
}

.gold-line::after {
  content:'';
  position:absolute;
  top:0;
  left:-150%;
  width:150%;
  height:100%;
  background:linear-gradient(90deg,transparent 0%,rgba(255,216,0,0.4) 30%,rgba(255,184,0,0.6) 50%,rgba(255,216,0,0.4) 70%,transparent 100%);
  animation:goldSweep 3s ease-in-out infinite;
}

@keyframes goldSweep {
  0%{left:-150%}
  100%{left:150%}
}

