  background:var(--cyan);
}
.gold-line.cyan::after {
background:linear-gradient(90deg,transparent 0%,rgba(6,182,212,0.4) 30%,rgba(103,232,249,0.6) 50%,rgba(6,182,212,0.4) 70%,transparent 100%);
