  box-shadow:
    0 10px 40px rgba(0,0,0,0.3),
    inset 0 0 0 1px rgba(255,255,255,0.08);
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.card-base:hover {
  transform: translateY(-4px) scale(1.01);
  box-shadow:
    0 16px 48px rgba(0,0,0,0.35),
    inset 0 0 0 1px rgba(255,255,255,0.12);
}

.card-gold {
  border:1px solid rgba(255,184,0,0.25);
  box-shadow:0 20px 60px rgba(0,0,0,0.3), 0 0 40px rgba(255,184,0,0.08);
}

.card-gold:hover {
  box-shadow:0 25px 70px rgba(0,0,0,0.35), 0 0 50px rgba(255,184,0,0.12);
}

.card-cyan {
  border:1px solid rgba(6,182,212,0.25);
  box-shadow:0 20px 60px rgba(0,0,0,0.3), 0 0 40px rgba(6,182,212,0.08);
}

.card-cyan:hover {
  box-shadow:0 25px 70px rgba(0,0,0,0.35), 0 0 50px rgba(6,182,212,0.12);
}

.card-violet {
  border:1px solid rgba(139,92,246,0.25);
  box-shadow:0 20px 60px rgba(0,0,0,0.3), 0 0 40px rgba(139,92,246,0.08);
}

.card-violet:hover {
  box-shadow:0 25px 70px rgba(0,0,0,0.35), 0 0 50px rgba(139,92,246,0.12);
}

.card-green {
  border:1px solid rgba(16,185,129,0.25);
  box-shadow:0 20px 60px rgba(0,0,0,0.3), 0 0 40px rgba(16,185,129,0.08);
}

.card-green:hover {
  box-shadow:0 25px 70px rgba(0,0,0,0.35), 0 0 50px rgba(16,185,129,0.12);
}

/* QUOTE CARD - PREMIUM STYLE */
.quote-card {
  background:linear-gradient(145deg,rgba(255,255,255,0.04),rgba(255,255,255,0.01));
  border-left:4px solid var(--gold);
  border-radius:20px;
  padding:3rem;
  max-width:90%;
  box-shadow:0 20px 60px rgba(0,0,0,0.3), 0 0 35px rgba(255,184,0,0.08);
  backdrop-filter: blur(16px);
  position:relative;
  overflow:hidden;
}

.quote-card::before {
  content: '';
  position:absolute;
  top:0;
  left:0;
  right:0;
  height:4px;
  background:linear-gradient(90deg,transparent,var(--gold),transparent);
  transform:scaleX(0);
  transition:transform 0.6s ease;
}

.quote-card:hover::before {
  transform:scaleX(1);
}

.quote-card .q-sub {
  font-size:2.2rem;
  font-weight:300;
  color:var(--text-secondary);
  margin-bottom:0.8rem;
  line-height:1.4;
}

.quote-card .q-main {
  font-size:3.2rem;
  font-weight:700;
  color:var(--text-primary);
  line-height:1.35;
  letter-spacing:-0.01em;
}

.quote-card .q-attribution {
  font-size:1.4rem;
  color:var(--text-muted);
  margin-top:1.2rem;
  font-weight:300;
  letter-spacing:-0.005em;
}

/* Color variants */
.quote-card.card-cyan { border-left-color:var(--cyan); }
.quote-card.card-cyan::before { background:linear-gradient(90deg,transparent,var(--cyan),transparent); }
.quote-card.card-violet { border-left-color:var(--violet); }
.quote-card.card-violet::before { background:linear-gradient(90deg,transparent,var(--violet),transparent); }
.quote-card.card-red { border-left-color:var(--red); }
.quote-card.card-red::before { background:linear-gradient(90deg,transparent,var(--red),transparent); }
.quote-card.card-orange { border-left-color:var(--orange); }
.quote-card.card-orange::before { background:linear-gradient(90deg,transparent,var(--orange),transparent); }
.quote-card.card-green { border-left-color:var(--green); }
.quote-card.card-green::before { background:linear-gradient(90deg,transparent,var(--green),transparent); }

/* BIG NUMBER - WITH SUBTLE ANIMATION */
.big-number {
  font-size:clamp(6rem, 10vw, 11rem);
  font-weight:900;
  color:var(--gold);
  line-height:1;
  letter-spacing:-0.03em;
  text-shadow:
    0 2px 8px rgba(0,0,0,0.3),
    0 0 12px rgba(255,184,0,0.2);
  display:inline-block;
  position:relative;
}

.big-number::after {
  content: '';
  position:absolute;
  bottom:-8px;
  left:50%;
  transform:translateX(-50%);
  width:60%;
  height:4px;
  background:linear-gradient(90deg,transparent,var(--gold),transparent);
  border-radius:2px;
  opacity:0;
  transition:all 0.4s ease;
}

.big-number:hover::after {
  width:80%;
  opacity:0.7;
}

.big-number-sm {
  font-size:clamp(4rem, 7vw, 5rem);
  font-weight:900;
  color:var(--gold);
  line-height:1;
}

/* LIMITS GRID - WITH HOVER EFFECTS */
.limits-grid {
  display:flex;
  gap:2.5rem;
  margin-top:2rem;
  flex-wrap:wrap;
  justify-content:center;
}

.limit-item {
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:1.2rem;
  transition:all 0.4s ease;
  background:var(--glass);
  border:1px solid var(--glass-light);
  border-radius:16px;
  padding:1.5rem;
  backdrop-filter: blur(12px);
  min-width:180px;
}

.limit-item:hover {
  transform:translateY(-6px) scale(1.02);
  box-shadow:0 12px 32px rgba(0,0,0,0.25);
  border-color:rgba(255,184,0,0.2);
}

.limit-visual {
  width:180px;
  height:180px;
  border-radius:16px;
  overflow:hidden;
  position:relative;
  isolation:isolate;
  background:var(--glass);
  border:1px solid rgba(255,255,255,0.08);
}

.limit-visal img {
  width:100%;
  height:100%;
  display:block;
  object-fit:cover;
  transition:transform 0.6s ease;
}

.limit-item:hover .limit-visual img {
  transform:scale(1.05);
}

.limit-image-overlay {
  position:absolute;
  inset:0;
  pointer-events:none;
  background:linear-gradient(180deg,rgba(7,11,23,0.02),rgba(7,11,23,0.5));
}

.limit-visual.is-limited::after {
  content:'';
  position:absolute;
  inset:0;
  pointer-events:none;
  background:linear-gradient(135deg,transparent 48%,rgba(239,68,68,0.3) 49%,rgba(239,68,68,0.3) 51%,transparent 52%);
  opacity:0.7;
}

.limit-visual.is-open {
  box-shadow:inset 0 0 30px rgba(34,211,238,0.08);
  border:1px solid rgba(34,211,238,0.2);
}

.limit-visual.image-failed {
  background:var(--glass);
  box-shadow:inset 0 0 20px rgba(255,255,255,0.06);
  border:1px solid rgba(255,255,255,0.1);
}

.limit-visual.image-failed img {
  display:none;
}

.limit-label {
  font-size:1.6rem;
  font-weight:700;
  color:var(--text-muted);
  letter-spacing:-0.005em;
}

.limit-sub {
  font-size:1.1rem;
  color:var(--text-secondary);
}

/* BOTTLENECK - ENHANCED */
.bottleneck-visual {
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:1.5rem;
  margin-top:1.5rem;
}

.b-old {
  font-size:3.2rem;
  font-weight:700;
  color:var(--text-muted);
  text-decoration:line-through;
  opacity:0.6;
  position:relative;
}

.b-arrow {
  font-size:2.4rem;
  color:var(--gold);
  animation:bounceArrow 2.5s ease-in-out infinite;
  text-shadow:0 0 8px rgba(255,184,0,0.3);
}

@keyframes bounceArrow {
  0%,100%{transform:translateY(0) scale(1);}
  30%{transform:translateY(-8px) scale(1.1);}
  50%{transform:translateY(4px) scale(0.95);}
  70%{transform:translateY(-4px) scale(1.05);}
  100%{transform:translateY(0) scale(1);}
}

.b-now {
  font-size:1.5rem;
  color:var(--gold);
  font-weight:600;
  letter-spacing:-0.005em;
}

.b-items {
  display:flex;
  gap:1.8rem;
  margin-top:1rem;
}

.b-items span {
  font-size:2.8rem;
  font-weight:800;
  padding:1rem 1.8rem;
  background:var(--glass);
  border-radius:14px;
  border:1px solid var(--glass-light);
  transition:all 0.3s ease;
  backdrop-filter: blur(10px);
}

.b-items span:hover {
  transform:translateY(-3px) scale(1.03);
  box-shadow:0 8px 20px rgba(0,0,0,0.15);
}

.b-items .b-ask {
  color:var(--cyan);
  border-left:4px solid var(--cyan);
  box-shadow=0 0 25px rgba(34,211,238,0.1);
}

.b-items .b-judge {
  color:var(--violet);
  border-left:4px solid var(--violet);
  box-shadow=0 0 25px rgba(139,92,246,0.1);
}

.b-items .b-act {
  color:var(--green);
  border-left:4px solid var(--green);
  box-shadow=0 0 25px rgba(34,197,94,0.1);
}

/* SPLIT VIEW - ENHANCED */
.split-view {
  display:flex;
  gap:0;
  border-radius:20px;
  overflow:hidden;
  box-shadow:0 8px 32px rgba(0,0,0,0.25);
}

.split-side {
  flex:1;
  padding:3rem 2.5rem;
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:1.2rem;
  min-width:360px;
  transition:all 0.4s ease;
}

.split-worried {
  background:rgba(239,68,68,0.08);
  border-right:1px solid rgba(255,255,255,0.06);
}

.split-worried:hover {
  background:rgba(239,68,68,0.12);
}

.split-over {
  background:rgba(34,197,94,0.06);
}

.split-over:hover {
  background:rgba(34,197,94,0.09);
}

.split-label {
  font-size:1.1rem;
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:0.12em;
}

.split-worried .split-label {
  color:var(--red);
  text-shadow:0 0 8px rgba(239,68,68,0.2);
}

.split-over .split-label {
  color:var(--green);
  text-shadow:0 0 8px rgba(34,197,94,0.2);
}

.split-person-visual {
  width:320px;
  height:260px;
  border-radius:20px;
  overflow:hidden;
  position:relative;
  isolation:isolate;
  background:var(--glass);
  border:1px solid var(--glass-light);
}

.split-person-visual img {
  width=100%;
  height=100%;
  display:block;
  object-fit:cover;
  transition:transform 0.5s ease;
}

.split-person-image:hover .split-person-visual img {
  transform:scale(1.03);
}

.split-person-overlay {
  position=absolute;
  inset:0;
  pointer-events:none;
  background:linear-gradient(180deg,rgba(7,11,23,0.02),rgba(7,11,23,0.45));
}

.split-person-visual.image-failed {
  background:var(--glass);
}

.split-person-visual.image-failed img {
  display:none;
}

.split-thought {
  font-size:1.4rem;
  color:var(--text-secondary);
  font-style:italic;
  max-width:280px;
  line-height:1.4;
}

.split-tag {
  font-size:0.9rem;
  font-weight:600;
  opacity:0.7;
  letter-spacing:-0.005em;
}

/* PROMPT CARDS - PREMIUM */
.prompt-card {
  background:linear-gradient(145deg,rgba(255,255,255,0.04),rgba(255,255,255,0.01));
  border-radius:18px;
  padding:2.5rem;
  min-width:560px;
  max-width:750px;
  border:1px solid var(--glass-light);
  backdrop-filter: blur(16px);
  box-shadow:0 15px 35px rgba(0,0,0,0.2);
  transition:all 0.4s ease;
}

.prompt-card:hover {
  transform:translateY(-3px) scale(1.01);
  box-shadow:0 20px 45px rgba(0,0,0,0.25);
}

.prompt-generic {
  border:1px solid rgba(148,163,184,0.15);
}

.prompt-contextual {
  border:1px solid rgba(6,182,212,0.25);
  box-shadow:0 0 30px rgba(6,182,212,0.08);
}

.prompt-label {
  font-size:0.9rem;
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:0.1em;
  margin-bottom:1.2rem;
  text-shadow:0 1px 2px rgba(0,0,0,0.1);
}

.prompt-label.generic {
  color:var(--text-muted);
}

.prompt-label.contextual {
  color:var(--cyan);
  text-shadow=0 0 8px rgba(6,182,212,0.2);
}

.prompt-text {
  font-size:1.5rem;
  color:var(--text-secondary);
  font-weight=300;
  line-height=1.7;
  font-style:italic;
  max-width=600px;
}

.prompt-result {
  font-size:1.25rem;
  margin-top:1.2rem;
  padding=1rem 1.3rem;
  border-radius=10px;
  font-weight=500;
  letter-spacing:-0.005em;
}

.prompt-generic .prompt-result {
  background:rgba(255,255,255,0.04);
  border:1px solid rgba(255,255,255,0.08);
}

.prompt-contextual .prompt-result {
  background:rgba(6,182,212,0.05);
  border-left:3px solid var(--cyan);
  color:var(--text-primary);
}

/* TOOL CONSTELLATION - ENHANCED */
.constellation {
  position:relative;
  width:1400px;
  height:950px;
  margin:0 auto;
  perspective:1000px;
}

#scene-ai-ecosystem .constellation {
  margin:0;
  padding:4rem;
}

#scene-ai-ecosystem .constellation-center {
  position:absolute;
  left:50%;
  top=50%;
  transform:translate(-50%,-50%) rotateY(0deg) rotateX(0deg);
  z-index:3;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  width:min(800px,75%);
  text-align:center;
  pointer-events:none;
  transition:all 0.6s ease;
}

#scene-ai-ecosystem .constellation-center:hover {
  transform:translate(-50%,-50%) rotateY(5deg) rotateX(-3deg) scale(1.02);
}

#scene-ai-ecosystem .constellation-center .slide-label {
  margin-bottom:1.2rem;
}

#scene-ai-ecosystem .constellation-center .s-heading {
  margin:0;
  max-width:800px;
  line-height:1.12;
}

#scene-ai-ecosystem .constellation-origin {
  position:absolute;
  left=50%;
  top=50%;
  width=0;
  height=0;
  z-index=2;
}

#connections-canvas {
  position:absolute;
  inset:0;
  width=100%;
  height=100%;
  pointer-events:none;
  z-index=0;
}

.tool-node {
  position=absolute;
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:.8rem;
  cursor=pointer;
  z-index:2;
  opacity:0;
  transform:translate(-50%,-50%) scale(.8);
  transition:all .5s cubic-bezier(.175,.885,.32,1.275);
  backdrop-filter: blur(8px);
  background:rgba(17,24,39,.6);
  border:1px solid rgba(255,255,255,.08);
  border-radius:16px;
  padding:.8rem;
  box-shadow:0 4px 16px rgba(0,0,0,.2);
}

.tool-node:hover {
  transform:translate(-50%,-50%) scale(1.05) rotate(2deg);
  border-color:var(--gold);
  box-shadow=0 8px 24px rgba(0,0,0,.25), 0 0 16px rgba(255,184,0,.15);
}

.tool-node .tn-icon {
  width:90px;
  height=90px;
  border-radius=20px;
  display:flex;
  align-items:center;
  justify-content:center;
  border=1px solid rgba(255,255,255,.1);
  background:rgba(17,24,39,.8);
  transition:all .4s ease;
}

.tool-node:hover .tn-icon {
  border-color:var(--gold);
  box-shadow=0 0 20px rgba(255,184,0,.2);
  background:rgba(255,184,0,.05);
}

.tool-node .tn-name {
  font-size:1.6rem;
  font-weight=700;
  color:var(--text-primary);
  white-space:nowrap;
  letter-spacing:-.005em;
  text-shadow:0 1px 2px rgba(0,0,0,.1);
}

.tool-node .tn-cap {
  font-size:1.2rem;
  font-weight=500;
  color:var(--text-secondary);
  white-space:nowrap;
  letter-spacing:-.003em;
}

/* 10/10 DISPLAY - ENHANCED */
.ten-display {
  display:flex;
  align-items:baseline;
  gap:1rem;
  margin:.8rem 0;
}

.ten-number {
  font-size:clamp(5rem, 9vw, 8rem);
  font-weight=900;
  color:var(--gold);
  line-height=1;
  text-shadow=0 0 12px rgba(255,184,0,.15);
}

.ten-label {
  font-size:1.8rem;
  color:var(--text-muted);
  font-weight=300;
  letter-spacing:-.005em;
}

/* SPOTLIGHT CARDS - PREMIUM GLASS */
.spotlight-card {
  background:linear-gradient(145deg,rgba(255,255,255,.04),rgba(255,255,255,.01));
  border-radius:20px;
  padding:3rem;
  text-align:center;
  min-width:650px;
