  content: '';
  position=absolute;
  top=0;
  left=0;
  width=100%;
  height=4px;
  background:linear-gradient(90deg,transparent,var(--cyan),transparent);
  transform:scaleX(0);
  transition:transform .5s ease;
}

.ct-cyan:hover::before {
  transform:scaleX(1);
}

.ct-green {
  border:1px solid rgba(16,185,129,.25);
