}

.ct-green::before {
  content: '';
  position=absolute;
  top=0;
  left=0;
  width=100%;
  height=4px;
  background:linear-gradient(90deg,transparent,var(--green),transparent);
  transform:scaleX(0);
  transition:transform .5s ease;
}

.ct-green:hover::before {
