}

.ct-cyan .big-number-sm {
  color:var(--cyan);
}

.ct-green .big-number-sm {
  color:var(--green);
}

/* NOUN LIST - ENHANCED */
.nouns-list {
  display:flex;
  flex-direction:column;
  gap:.7rem;
  align-items=center;
}

.nouns-list span {
  font-size=2.6rem;
  font-weight=300;
  color:#64758B;
  letter-spacing:-.005em;
  text-shadow=0 1px 2px rgba(0,0,0,.1);
  transition:all .3s ease;
}

.nouns-list span:hover {
  transform:scale(1.05);
  color:var(--text-primary);
  text-shadow=0 0 8px rgba(255,255,255,.2);
}

/* QUESTION LIST - ENHANCED */
.questions-list {
  display:flex;
  flex-direction:column;
  gap:1rem;
  align-items:flex-start;
}

.questions-list span {
  font-size=1.8rem;
  font-weight=400;
  padding:.5rem 0;
  line-height=1.5;
  color:var(--text-secondary);
  background:var(--glass);
  padding:.8rem 1.2rem;
  border-radius=10px;
  border:1px solid var(--glass-light);
  transition:all .3s ease;
}

.questions-list span:hover {
  background=rgba(255,184,0,.05);
  color=var(--text-primary);
  transform:translateX(4px);
}

/* EQUATION DISPLAY (DANGER) - ENHANCED */
.equation-display {
  display:flex;
  align-items=center;
  gap:1.2rem;
  justify-content=center;
  margin-top:1.5rem;
}

.eq-part {
  font-size=clamp(6rem, 10vw, 8rem);
  font-weight=900;
  letter-spacing:-.02em;
  line-height=1;
}

.eq-one {
  color:var(--text-primary);
  text-shadow=0 0 8px rgba(255,255,255,.15);
}

.eq-op {
  font-size=clamp(3.5rem, 6vw, 4.5rem);
  color=var(--red);
  opacity=.6;
  text-shadow=0 0 6px rgba(239,68,68,.2);
}

.eq-tenk {
  color:var(--red);
  text-shadow=0 0 15px rgba(239,68,68,.3);
  position=relative;
}

.eq-tenk::after {
  content: '';
  position=absolute;
  bottom:-8px;
  left=50%;
  transform:translateX(-50%);
  width=70%;
  height=3px;
  background:linear-gradient(90deg,transparent,var(--red),transparent);
  border-radius=2px;
  opacity=.6;
}

.eq-caption {
  font-size=1.6rem;
  color:var(--text-muted);
  font-weight=300;
  margin-top:1.2rem;
  max-width=700px;
}

.danger-grid {
  display:flex;
  flex-wrap:wrap;
  gap:1.4rem;
  justify-content=center;
  margin-top:1.8rem;
  width=100%;
}

.d-node {
  display:flex;
  align-items=center;
  gap:.9rem;
  padding=1rem 1.6rem;
  border-radius=12px;
  font-size=1.4rem;
  color=var(--text-secondary);
  background:linear-gradient(145deg,rgba(255,255,255,.04),rgba(255,255,255,.01));
  border:1px solid var(--glass-light);
  backdrop-filter:blur(10px);
  transition:all .3s ease;
  position:relative;
  overflow:hidden;
}

.d-node:hover {
  transform:translateY(-3px) scale(1.03);
  box-shadow=0 8px 20px rgba(0,0,0,.15);
}

.d-node .d-icon {
  display=inline-flex;
  align-items=center;
  justify-content=center;
  width=28px;
  height=28px;
}

.d-node .d-icon svg {
  width=20px;
  height=20px;
}

.d-node.d-hallucination {
  border=1px solid rgba(239,68,68,.3);
  background=linear-gradient(145deg,rgba(239,68,68,.05),rgba(239,68,68,.02));
}

.d-node.d-security {
  border=1px solid rgba(249,115,22,.3);
  background=linear-gradient(145deg,rgba(249,115,22,.05),rgba(249,115,22,.02));
}

.d-node.d-scaling {
  border=1px solid rgba(239,68,68,.3);
  background=linear-gradient(145deg,rgba(239,68,68,.05),rgba(239,68,68,.02));
}

.d-node.d-confidence {
  border=1px solid rgba(249,115,22,.3);
  background=linear-gradient(145deg,rgba(249,115,22,.05),rgba(249,115,22,.02));
  box-shadow=0 0 20px rgba(249,115,22,.08);
}

/* UPDATE STACK - ENHANCED */
.update-stack {
  display:flex;
  flex-direction:column;
  gap:1.2rem;
  align-items=center;
}

.update-item {
  font-size=3rem;
  font-weight=500;
  color=var(--text-secondary);
  line-height=1.4;
  letter-spacing:-.005em;
  text-align=center;
  max-width=700px;
  padding:.8rem 1.5rem;
  background:var(--glass);
  border-radius=12px;
  border:1px solid var(--glass-light);
  transition:all .3s ease;
}

.update-item:hover {
  transform:scale(1.02);
  background=rgba(255,184,0,.03);
  color=var(--text-primary);
}

/* FINAL QUESTION - DRAMATIC */
.final-question {
  font-size=clamp(5rem, 9vw, 7.5rem);
  font-weight=900;
  color=var(--text-primary);
  text-align=center;
  line-height=1.1;
  max-width=90%;
  letter-spacing:-.02em;
  text-shadow=
    0 2px 8px rgba(0,0,0,.3),
    0 0 15px rgba(255,184,0,.25);
  position=relative;
}

.final-question::after {
  content: '';
  position=absolute;
  bottom:-10px;
  left=50%;
  transform:translateX(-50%);
  width=50%;
  height=4px;
  background:linear-gradient(90deg,transparent,var(--gold-gradient),transparent);
  border-radius=2px;
  opacity=0;
  transition:all .5s ease;
}

.final-question:hover::after {
  width:80%;
  opacity:.6;
}

/* FINAL BLOCK - ENHANCED */
.final-block p {
  font-size=2rem;
  color=var(--text-secondary);
  font-weight=300;
  line-height=1.6;
  max-width=85%;
  margin:0 auto 1.5rem;
  text-align=center;
  padding:0 2rem;
}

.final-block .fq {
  font-size=2.8rem;
  font-weight=600;
  margin-bottom=.8rem;
}

.final-block .fq-main {
  font-size=4.5rem;
  font-weight=700;
  letter-spacing:-.01em;
}

/* THANK YOU - ENHANCED */
.thank-you-text {
  font-size=clamp(4rem, 7vw, 6rem);
  font-weight=700;
  color=var(--gold);
  text-align=center;
  text-shadow=
    0 0 20px rgba(255,184,0,.15),
    0 0 40px rgba(255,184,0,.08);
  letter-spacing:-.01em;
  position=relative;
}

.thank-you-text::after {
  content: '';
  position=absolute;
  bottom:-8px;
  left=50%;
  transform:translateX(-50%);
  width=60%;
  height=3px;
  background:linear-gradient(90deg,transparent,var(--gold),transparent);
  border-radius=2px;
  opacity=0;
  transition:all .4s ease;
}

.thank-you-text:hover::after {
  width=80%;
  opacity=.5;
}

/* AMBIENT GLOWS - DEFINED IN :ROOT */

/* PARALLAX - ENHANCED */
#parallax-back {
  background:radial-gradient(ellipse 60% 50% at 20% 30%,rgba(7,11,23,.7),transparent),radial-gradient(ellipse 40% 40% at 80% 70%,rgba(17,26,46,.3),transparent);
  opacity:.7;
  background-attachment:fixed;
}

#parallax-mid {
  background:radial-gradient(ellipse 50% 30% at 50% 20%,rgba(255,184,0,.02),transparent),radial-gradient(ellipse 30% 40% at 70% 80%,rgba(34,211,238,.02),transparent);
  opacity:.4;
  background-attachment:fixed;
}

/* HUD - REFINE FOR 75" */
#hud {
  position:fixed;
  bottom:2.5rem;
  left=50%;
  transform:translateX(-50%);
  display:flex;
  align-items=center;
  gap:1.2rem;
  z-index:1000;
  opacity=1;
  transition:opacity .5s ease;
  background:rgba(17,24,39,.6);
  padding:.8rem 1.5rem;
  border-radius:16px;
  border:1px solid rgba(255,255,255,.08);
  backdrop-filter:blur(10px);
}

#hud.hud-hidden {
  opacity:.12;
}

#hud.hud-hidden:hover {
  opacity:1;
}

.hud-btn {
  background=rgba(17,24,39,.7);
  border=1px solid rgba(255,255,255,.08);
  color=var(--gold);
  font-size=1.3rem;
  width=48px;
  height=48px;
  border-radius=50%;
  cursor:pointer;
  display:flex;
  align-items=center;
  justify-content=center;
  transition:all .3s ease;
  box-shadow=0 4px 12px rgba(0,0,0,.2);
}

.hud-btn:hover {
  background=rgba(255,184,0,.12);
  transform=scale(1.08);
  box-shadow=0 6px 16px rgba(0,0,0,.25);
}

.hud-btn:active {
  transform:scale(.95);
}

#progress-bar {
  width=140px;
  height=3px;
  background=rgba(255,255,255,.06);
  border-radius=2px;
  overflow:hidden;
  background:linear-gradient(90deg,rgba(255,255,255,.02),rgba(255,255,255,.1));
}

#progress-fill {
  height=100%;
  width=0%;
  background:linear-gradient(90deg,var(--gold),var(--gold-bright));
  transition:width .5s ease;
  border-radius=2px;
}

/* ZONE LABELS - ENHANCED */
#zone-labels {
  position=fixed;
  inset=0;
  display:flex;
  flex-wrap=wrap;
  align-items=center;
  justify-content=center;
  gap:2.5rem;
  pointer-events=none;
  z-index=500;
  opacity=0;
  transition:opacity .6s ease;
  background=rgba(0,0,0,.2);
  padding=2rem;
  border-radius=16px;
  backdrop-filter:blur(8px);
}

#zone-labels.active {
  opacity=1;
  pointer-events=auto;
}

.zl-item {
  font-size=1.3rem;
  font-weight=700;
  color=var(--text-muted);
  text-transform=uppercase;
  letter-spacing=.08em;
  cursor=pointer;
  padding=.6rem 1.4rem;
  border=1px solid rgba(255,255,255,.06);
  border-radius=10px;
  transition:all .3s;
  background=rgba(7,11,23,.7);
  backdrop-filter:blur(4px);
}

.zl-item:hover {
  color=var(--gold);
  border-color=var(--gold);
  background=rgba(255,184,0,.08);
  transform:translateY(-2px) scale(1.03);
  box-shadow=0 4px 12px rgba(0,0,0,.15);
}

/* PARTICLES - FINISHED IN :ROOT */

/* KEYFRAMES - REFINED */
@keyframes elasticBounce {
  0%{transform:scale(0.2);opacity:0}
  50%{transform:scale(1.1)}
  70%{transform:scale(0.92)}
  85%{transform:scale(1.03)}
  100%{transform:scale(1);opacity:1}
}
.elastic-bounce {
  animation:elasticBounce 1.3s cubic-bezier(.68,-.55,.27,1.55) forwards;
}

@keyframes fadeUp {
  from{opacity:0;transform:translateY(18px)}
  to{opacity:1;transform:translateY(0)}
}
.fade-up {
  animation:fadeUp .7s ease forwards;
}

@keyframes slideInLeft {
  from{transform:translateX(-100%);opacity=0}
  to{transform:translateX(0);opacity=1}
}
@keyframes slideInRight {
  from{transform:translateX(100%);opacity=0}
  to{transform:translateX(0);opacity=1}
}

@keyframes pulseGlow {
  0%,100%{text-shadow=0 0 20px rgba(255,184,0,.3),0 0 40px rgba(255,184,0,.1)}
  50%{text-shadow=0 0 40px rgba(255,184,0,.5),0 0 80px rgba(255,184,0,.2)}
}
.word-fade span {
  display=inline-block;
  opacity=0;
  transition:opacity .4s ease;
}

/* RESPONSIVE - OPTIMIZED FOR LARGE SCREENS */
@media (max-width:1920px) {
  .scene-inner {
    min-width:480px;
    max-width:900px;
    padding:2.5rem;
