    min-width=350px;
  }
  .d-node {
    font-size=.95rem;
  }
  .update-item {
    font-size=1.8rem;
  }
}

@media (max-width:1024px) {
  .scene-inner {
    min-width=280px;
    max-width:500px;
    padding=1.5rem;
  }
  h1,.s-title {
    font-size=2.8rem!important;
  }
  .s-question {
