/* REDUCED MOTION - ENHANCED */
@media (prefers-reduced-motion:reduce) {
  *,*::before,*::after {
    animation-duration:.01ms!important;
    transition-duration:.01ms!important;
  }
  .gold-line::after {
    animation:none;
    background:var(--gold);
  }
  .b-arrow {
    animation:none;
  }
  .final-question::after {
    animation:none;
    background:linear-gradient(90deg,transparent,var(--gold),transparent);
    opacity=.4;
  }
  .thank-you-text::after {
    animation:none;
    background:linear-gradient(90deg,transparent,var(--gold),transparent);
    opacity=.3;
  }
}

/* PRINT STYLES - BASIC */
@media print {
  body {
    background:white;
    color=black;
  }
  .scene-inner {
    background=white;
    border=1px solid #ddd;
    box-shadow:none;
  }
  .text-gold, .text-cyan, .text-violet {
    color=black;
  }
  .gold-line {
    background=#ddd;
  }
}
